import SwiftUI
import NaberiusCore

struct LibraryView:View {
    @Bindable var session:Session
    private var personal:Bool {session.libraryPersonal}
    @State private var search=""
    @State private var editing:Reference?
    private var references:[Reference]{personal ? session.library : session.document?.references ?? []}
    var body:some View{
        VStack(spacing:12){
            HStack{Picker(L10n.text("Biblioteca"),selection:$session.libraryPersonal){Text(L10n.text("Del documento")).tag(false);Text(L10n.text("Personal")).tag(true)}.pickerStyle(.segmented).frame(width:290);Spacer();Button{editing=Reference()}label:{Label(L10n.text("Nueva"),systemImage:"plus")};Button(L10n.text("Importar…")){session.importReferences(personal:personal)}}
            TextField(L10n.text("Buscar referencias"),text:$search).textFieldStyle(.roundedBorder)
            if !personal && session.document == nil{ContentUnavailableView(L10n.text("Abre un documento"),systemImage:"doc",description:Text(L10n.text("La biblioteca personal está disponible sin abrir documentos.")))}
            else if references.isEmpty{ContentUnavailableView(L10n.text("Las fuentes de tus ideas"),systemImage:"books.vertical",description:Text(L10n.text("Añade una referencia o importa BibTeX, BibLaTeX, RIS o CSL-JSON.")))}
            else{List{ForEach(references.filter{search.isEmpty || ($0.title+$0.authors).localizedCaseInsensitiveContains(search)}){r in HStack{VStack(alignment:.leading,spacing:5){Text(r.title.isEmpty ? L10n.text("Sin título") : r.title).font(.headline);Text(r.authors+" · "+r.year).font(.caption).foregroundStyle(.secondary)};Spacer();Menu{Button(L10n.text("Editar…")){editing=r};if personal && session.document != nil{Button(L10n.text("Copiar al documento")){session.mutate(L10n.text("Copiar referencia")){d in if let i=d.references.firstIndex(where:{$0.id==r.id}){d.references[i]=r}else{d.references.append(r)}};session.refreshCitations()}};if !personal{Button(L10n.text("Copiar a biblioteca personal")){if let i=session.library.firstIndex(where:{$0.id==r.id}){session.library[i]=r}else{session.library.append(r)};session.persistLocal()}};Button(L10n.text("Eliminar registro"),role:.destructive){if personal{session.library.removeAll{$0.id==r.id};session.persistLocal()}else{session.mutate(L10n.text("Eliminar referencia")){$0.references.removeAll{$0.id==r.id}};session.refreshCitations()}}}label:{Image(systemName:"ellipsis")}}.padding(.vertical,5)}}}
            Text(personal ? L10n.text("Los documentos conservan sus propias copias. Los cambios se transfieren solo con «Copiar al documento».") : L10n.text("Estas referencias viajan dentro del archivo .nab, aunque cambie tu biblioteca personal.")).font(.caption).foregroundStyle(.secondary).frame(maxWidth:.infinity,alignment:.leading)
        }.padding(22).sheet(item:$editing){reference in ReferenceForm(reference:reference){r in if personal{if let i=session.library.firstIndex(where:{$0.id==r.id}){session.library[i]=r}else{session.library.append(r)};session.persistLocal()}else{session.mutate(L10n.text("Editar referencia")){d in if let i=d.references.firstIndex(where:{$0.id==r.id}){d.references[i]=r}else{d.references.append(r)}};session.refreshCitations()};editing=nil}}
    }
}
struct ReferenceForm:View {
    @State var reference:Reference
    let save:(Reference)->Void
    @Environment(\.dismiss) private var dismiss
    var body:some View{VStack(spacing:0){HStack{Text(L10n.text("Referencia bibliográfica")).font(.title2.weight(.semibold));Spacer();Button(L10n.text("Cancelar")){dismiss()};Button(L10n.text("Guardar")){save(reference)}.buttonStyle(.borderedProminent).disabled(reference.title.trimmingCharacters(in:.whitespaces).isEmpty)}.padding(22);Divider();Form{Picker(L10n.text("Tipo"),selection:$reference.type){Text(L10n.text("Artículo")).tag("article-journal");Text(L10n.text("Libro")).tag("book");Text(L10n.text("Capítulo")).tag("chapter");Text(L10n.text("Tesis")).tag("thesis");Text(L10n.text("Informe")).tag("report");Text(L10n.text("Sitio web")).tag("webpage");Text(L10n.text("Ponencia")).tag("paper-conference");Text(L10n.text("Manuscrito")).tag("manuscript");if !["article-journal","book","chapter","thesis","report","webpage","paper-conference","manuscript"].contains(reference.type) {Text(reference.type).tag(reference.type)}};TextField(L10n.text("Título"),text:$reference.title);TextField(L10n.text("Autores: Apellido, Nombre; …"),text:$reference.authors);TextField(L10n.text("Año"),text:$reference.year);TextField(L10n.text("Revista / libro"),text:$reference.container);TextField(L10n.text("Editorial"),text:$reference.publisher);TextField(L10n.text("Volumen"),text:$reference.volume);TextField(L10n.text("Número"),text:$reference.issue);TextField(L10n.text("Páginas"),text:$reference.pages);TextField(L10n.text("DOI"),text:$reference.doi);TextField(L10n.text("URL"),text:$reference.url);if let imported=reference.imported {Section(L10n.text("Datos de importación")) {Text(L10n.text("Los campos adicionales se conservan en .nab y CSL-JSON. BibTeX conserva los campos originales de entradas BibTeX/BibLaTeX; al exportar otros formatos se usan los campos del formulario.")).font(.caption).foregroundStyle(.secondary);ForEach(imported.warnings,id:\.self){Text($0).font(.caption)};DisclosureGroup(L10n.text("Ver datos originales")) {Text(imported.original).font(.system(size:11,design:.monospaced)).textSelection(.enabled)}}};Text(L10n.text("Los campos vacíos se conservan vacíos. No se consultan servicios en línea.")).font(.caption).foregroundStyle(.secondary)}.formStyle(.grouped)}.frame(width:610,height:630)}
}
